-- Add content_json column to weekly_recaps for rich tactical storybook content
-- This stores the full storybook payload (title, content, missions, achievements,
-- parentPrompt, imagePrompts) generated by the Groq tactical storybook engine.

alter table public.weekly_recaps
  add column if not exists content_json jsonb not null default '{}'::jsonb;

-- Index for querying storybook content by child
create index if not exists weekly_recaps_content_idx
  on public.weekly_recaps (child_id, week_start desc);
